    fn negative_zero_loose_equals_positive_zero() {
        // -0 == +0
        let neg_zero = Value::Float(Float64::new(-0.0));
        let pos_zero = Value::Float(Float64::new(0.0));
        assert!(InterpreterCore::abstract_eq_values(&neg_zero, &pos_zero));
    }

